package app.studyhub.security; import app.studyhub.infrastructure.UserRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserRepository users; public JwtFilter(JwtService jwt,UserRepository users){this.jwt=jwt;this.users=users;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var user=users.findByEmail(jwt.subject(h.substring(7))).orElseThrow();var auth=new UsernamePasswordAuthenticationToken(user.getEmail(),null,java.util.List.of(new SimpleGrantedAuthority(user.getRole())));SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ignored){}chain.doFilter(req,res);} }
